    # Each 5-line is a guide; colors along an attached arm are extended across its interior.
    # First copy the vertical color sequence across from a horizontal 5-line.
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == 5]
        if len(xs) < 2:
            continue
        left, right = min(xs), max(xs)
        seq, y = [], r + 1
        while y < h and grid[y][left] not in (0, 5):
            seq.append(grid[y][left]); y += 1
        if seq:
            for k, value in enumerate(seq):
                for x in range(left, right):
                    if grid[r + 1 + k][x] == 0:
                        out[r + 1 + k][x] = value
    # Then repeat a horizontal color tile upward along a vertical 5 guide.
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == 5]
        if len(ys) < 2 or ys != list(range(ys[0], ys[-1] + 1)):
            continue
        top, bottom, start = ys[0], ys[-1], c + 1
        if start >= w or not any(grid[bottom][x] not in (0, 5) for x in range(start, w)):
            continue
